mapper.select:
select v.*,v.PLEDGE_CONTRACT_NUMBER PLEDGE_CONTRACT_NUMBER_n, to_char(V.PLEDGE_TIMES_TO,'YYYY-MM-DD') PLEDGE_TIMES_TO_N, to_char(V.PLEDGE_TIMES_FROM,'YYYY-MM-DD') PLEDGE_TIMES_FROM_N
from ct_lon_contract_pledge v WHERE 1 = 1
AND v.CONTRACT_ID =#{contractId}

SELECT CONTRACT.CONTRACT_ID PLEDGE_DOC_ID, CONTRACT.CONTRACT_NAME PLEDGE_DOC_NAME, CONTRACT.APPROVAL_NUMBER PLEDGE_DOC_NUMBER, CONTRACT.DOC_CATEGORY PLEDGE_DOC_CATEGORY, CONTRACT.TIMES, CONTRACT.DUE_DATE, CONTRACT.DUE_DATE DUE_DATE_FORMAT, SUM(CONTRACT.DUE_AMOUNT) DUE_AMOUNT, nvl(SUM(CONTRACT.RECEIVED_AMOUNT),0) RECEIVED_AMOUNT, nvl(SUM(CONTRACT.DUE_AMOUNT),0) -nvl(SUM(CONTRACT.RECEIVED_AMOUNT),0) SURPLUS_AMOUNT, CASE WHEN CONTRACT.DOC_CATEGORY='CON_CONTRACT' THEN nvl(SUM(CONTRACT.INTEREST),0) ELSE ( nvl(SUM( CASE WHEN CONTRACT.CF_ITEM=55 THEN CONTRACT.DUE_AMOUNT ELSE 0 END) ,0)) END INTEREST, CASE WHEN CONTRACT.DOC_CATEGORY='CON_CONTRACT' THEN nvl(SUM(CONTRACT.PRINCIPAL),0) ELSE ( nvl(SUM( CASE WHEN CONTRACT.CF_ITEM=54 THEN CONTRACT.DUE_AMOUNT ELSE 0 END) ,0)) END PRINCIPAL FROM ( ( SELECT CON.CONTRACT_ID, CON.CONTRACT_NAME, CON.CONTRACT_NUMBER, PP.APPROVAL_NUMBER, CON.COMPANY_ID, CON_FLOW.CASHFLOW_ID, CON_FLOW.DUE_DATE, CON_FLOW.DUE_AMOUNT, CON_FLOW.RECEIVED_AMOUNT, CON_FLOW.TIMES, CON_FLOW.WRITE_OFF_FLAG, CON_FLOW.CF_ITEM, CON_FLOW.CF_TYPE, nvl(CON_FLOW.PRINCIPAL,0) PRINCIPAL, nvl(CON_FLOW.INTEREST,0) INTEREST, 'CON_CONTRACT' DOC_CATEGORY FROM CON_CONTRACT CON JOIN PRJ_PROJECT PP ON PP.PROJECT_ID=CON.PROJECT_ID JOIN CON_CONTRACT_CASHFLOW CON_FLOW ON CON.CONTRACT_ID=CON_FLOW.CONTRACT_ID WHERE CON.DATA_CLASS='NORMAL' AND CON_FLOW.CF_STATUS='RELEASE' AND CON_FLOW.CF_DIRECTION='INFLOW' AND CON_FLOW.CF_ITEM =1
AND (CON.CONTRACT_STATUS = 'INCEPT' OR (CON.CONTRACT_STATUS='PENDING' AND ( SELECT COUNT(1) FROM CON_CONTRACT FT WHERE FT.DATA_CLASS='CHANGE_REQ' AND FT.CONTRACT_STATUS='INCEPT' AND FT.REF_CONTRACT_ID=CON.CONTRACT_ID ) >0))
) UNION ( SELECT CON.CONTRACT_ID, CON.CONTRACT_NAME, CON.CONTRACT_NUMBER, CON.APPROVAL_NUMBER, CON.COMPANY_ID, CON_FLOW.QUOTATION_CASHFLOW_ID CASHFLOW_ID, CON_FLOW.DUE_DATE, CON_FLOW.DUE_AMOUNT, CON_FLOW.RECEIVED_AMOUNT, CON_FLOW.TIMES, CON_FLOW.WRITE_OFF_FLAG, CON_FLOW.CF_ITEM, CON_FLOW.CF_TYPE, nvl(CON_FLOW.PRINCIPAL,0) PRINCIPAL, nvl(CON_FLOW.INTEREST,0) INTEREST, 'FCT_CONTRACT' DOC_CATEGORY FROM FCT_CONTRACT CON JOIN FCT_QUOTATION_CASHFLOW CON_FLOW ON CON.CONTRACT_ID=CON_FLOW.CONTRACT_ID WHERE CON.DATA_CLASS='NORMAL' AND CON_FLOW.CF_STATUS='RELEASE' AND CON_FLOW.CF_DIRECTION='INFLOW' AND CON_FLOW.CF_ITEM IN(54,55)
AND (CON.CONTRACT_STATUS = 'INCEPT' OR (CON.CONTRACT_STATUS='PENDING' AND ( SELECT COUNT(1) FROM FCT_CONTRACT FT WHERE FT.DATA_CLASS='CHANGE_REQ' AND FT.CONTRACT_STATUS='INCEPT' AND FT.REF_CONTRACT_ID=CON.CONTRACT_ID ) >0)) ) ) CONTRACT WHERE 1=1
AND CONTRACT.CONTRACT_ID=#{pledgeDocId}
AND CONTRACT.DOC_CATEGORY=#{pledgeDocCategory}
AND CONTRACT.TIMES=#{times}
AND #{pledgeTimesFrom}<=CONTRACT.TIMES
AND #{pledgeTimesTo} >=CONTRACT.TIMES
GROUP BY CONTRACT.CONTRACT_ID, CONTRACT.CONTRACT_NAME , CONTRACT.CONTRACT_NUMBER , CONTRACT.APPROVAL_NUMBER, CONTRACT.DOC_CATEGORY , CONTRACT.TIMES, CONTRACT.DUE_DATE ORDER BY CONTRACT.TIMES
